6	function getSidebarDefaultOpen(): boolean {
7	  const match = typeof document !== "undefined"
8	    ? document.cookie.split(";").find((c) => c.trim().startsWith("sidebar:state="))
9	    : undefined;
10	  if (!match) return true;
11	  return match.split("=")[1]?.trim() === "true";
12	}
