56	function ReportCardSkeleton() {
57	  return (
58	    <Card className="h-full border-border/50 shadow-soft">
59	      <CardContent className="p-5 space-y-4">
60	        <div className="flex items-center gap-2">
61	          <Skeleton className="h-8 w-8 rounded-lg" />
62	          <Skeleton className="h-4 w-32" />
63	        </div>
64	        <div className="flex justify-center">
