82	const Reports = () => {
83	  const navigate = useNavigate();
84	  const [search, setSearch] = useState("");
85	  const [statusFilter, setStatusFilter] = useState("all");
86	  const [scoreFilter, setScoreFilter] = useState("all");
87	  const [sortBy, setSortBy] = useState("newest");
88	
89	  const { data: scans = [], isLoading } = useScans();
90	  const deleteScan = useDeleteScan();
91	  const { profile } = useAuth();
92	  const { isMonitored, toggleMonitoring } = useMonitoring();
93	  const canMonitor = profile?.plan === "pro" || profile?.plan === "agency";
94	
95	  const filtered = useMemo(() => {
96	    let list = [...scans];
97	
98	    // Search — matches URL, hostname, and page title
99	    if (search) {
100	      const q = search.toLowerCase();
101	      list = list.filter(
102	        (s) =>
103	          s.url.toLowerCase().includes(q) ||
104	          (s.page_title?.toLowerCase().includes(q) ?? false)
105	      );
106	    }
107	
108	    // Status filter
109	    if (statusFilter !== "all") {
110	      list = list.filter((s) => s.status === statusFilter);
111	    }
112	
113	    // Score filter
114	    if (scoreFilter !== "all") {
115	      list = list.filter((s) => {
116	        if (s.overall_score === null) return false;
117	        if (scoreFilter === "poor") return s.overall_score < 40;
118	        if (scoreFilter === "average") return s.overall_score >= 40 && s.overall_score < 70;
119	        if (scoreFilter === "good") return s.overall_score >= 70;
120	        return true;
121	      });
122	    }
123	
124	    // Sort
125	    list.sort((a, b) => {
126	      if (sortBy === "newest") return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
127	      if (sortBy === "oldest") return new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
128	      if (sortBy === "score-high") return (b.overall_score ?? 0) - (a.overall_score ?? 0);
129	      if (sortBy === "score-low") return (a.overall_score ?? 0) - (b.overall_score ?? 0);
130	      return 0;
131	    });
132	
133	    return list;
134	  }, [scans, search, statusFilter, scoreFilter, sortBy]);
135	
136	  const handleDelete = (scanId: string, hostname: string) => {
137	    deleteScan.mutate(scanId, {
138	      onSuccess: () => toast.success(`Scan for ${hostname} deleted`),
139	      onError: () => toast.error("Failed to delete scan"),
140	    });
141	  };
142	
143	  return (
144	    <PageTransition>
145	      <div className="space-y-6">
146	        <PageHeader title="My Reports" description="View and manage your CRO audit reports">
147	          <Button asChild>
148	            <Link to="/scan">
149	              <ScanLine className="mr-2 h-4 w-4" />
150	              New Scan
151	            </Link>
152	          </Button>
153	        </PageHeader>
154	
155	        {/* Filters */}
156	        <div className="flex flex-wrap gap-3">
157	          <div className="relative flex-1 min-w-[200px]">
158	            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
159	            <Input
160	              placeholder="Search by URL..."
161	              value={search}
162	              onChange={(e) => setSearch(e.target.value)}
163	              className="pl-9 border-border/50"
164	            />
165	          </div>
166	          <Select value={statusFilter} onValueChange={setStatusFilter}>
167	            <SelectTrigger className="w-36 border-border/50">
168	              <SelectValue placeholder="Status" />
169	            </SelectTrigger>
170	            <SelectContent>
171	              <SelectItem value="all">All Status</SelectItem>
172	              <SelectItem value="completed">Completed</SelectItem>
173	              <SelectItem value="analyzing">Analyzing</SelectItem>
174	              <SelectItem value="failed">Failed</SelectItem>
175	            </SelectContent>
176	          </Select>
177	          <Select value={scoreFilter} onValueChange={setScoreFilter}>
178	            <SelectTrigger className="w-36 border-border/50">
179	              <SelectValue placeholder="Score" />
180	            </SelectTrigger>
181	            <SelectContent>
182	              <SelectItem value="all">All Scores</SelectItem>
183	              <SelectItem value="poor">Poor (0-40)</SelectItem>
184	              <SelectItem value="average">Average (40-70)</SelectItem>
185	              <SelectItem value="good">Good (70+)</SelectItem>
186	            </SelectContent>
187	          </Select>
188	          <Select value={sortBy} onValueChange={setSortBy}>
189	            <SelectTrigger className="w-36 border-border/50">
190	              <SelectValue placeholder="Sort" />
191	            </SelectTrigger>
192	            <SelectContent>
193	              <SelectItem value="newest">Newest First</SelectItem>
194	              <SelectItem value="oldest">Oldest First</SelectItem>
195	              <SelectItem value="score-high">Score: High-Low</SelectItem>
196	              <SelectItem value="score-low">Score: Low-High</SelectItem>
197	            </SelectContent>
198	          </Select>
199	        </div>
200	
201	        {/* Report Cards Grid */}
202	        {isLoading ? (
203	          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
204	            {[1, 2, 3, 4, 5, 6].map((i) => <ReportCardSkeleton key={i} />)}
205	          </div>
206	        ) : filtered.length > 0 ? (
207	          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
208	            {filtered.map((scan) => {
209	              let hostname = scan.url;
210	              try { hostname = new URL(scan.url).hostname; } catch { /* keep raw */ }
211	              const displayHostname = hostname.replace("www.", "");
212	              const faviconUrl = `https://www.google.com/s2/favicons?domain=${hostname}&sz=32`;
213	
214	              return (
215	                <Link key={scan.id} to={`/reports/${scan.id}`}>
216	                  <Card className="group h-full border-border/50 shadow-soft hover:shadow-soft-md transition-all cursor-pointer">
217	                    <CardContent className="p-5">
218	                      {/* URL + menu */}
219	                      <div className="flex items-start justify-between">
220	                        <div className="flex items-center gap-2 min-w-0">
221	                          <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-muted/50 overflow-hidden">
222	                            <img
223	                              src={faviconUrl}
224	                              alt=""
225	                              className="h-4 w-4"
226	                              onError={(e) => {
227	                                const target = e.currentTarget;
228	                                target.style.display = "none";
229	                                const parent = target.parentElement;
230	                                if (parent) {
231	                                  const fallback = document.createElement("span");
232	                                  fallback.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="text-muted-foreground"><circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg>`;
233	                                  parent.appendChild(fallback);
234	                                }
235	                              }}
236	                            />
237	                          </div>
238	                          <span className="truncate text-sm font-medium text-foreground">
239	                            {displayHostname}
240	                          </span>
241	                        </div>
242	                        <DropdownMenu>
243	                          <DropdownMenuTrigger asChild onClick={(e) => e.preventDefault()}>
244	                            <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
245	                              <MoreVertical className="h-4 w-4 text-muted-foreground" />
246	                            </Button>
247	                          </DropdownMenuTrigger>
248	                          <DropdownMenuContent align="end">
249	                            <DropdownMenuItem onClick={() => navigate(`/reports/${scan.id}`)}>
250	                              <Eye className="mr-2 h-3.5 w-3.5" /> View Report
251	                            </DropdownMenuItem>
252	                            <DropdownMenuItem onClick={() => navigate(`/scan?url=${encodeURIComponent(scan.url)}&type=${scan.page_type}`)}>
253	                              <RefreshCw className="mr-2 h-3.5 w-3.5" /> Re-scan
254	                            </DropdownMenuItem>
255	                            <DropdownMenuSeparator />
256	                            {canMonitor ? (
257	                              <DropdownMenuItem
258	                                onClick={(e) => {
259	                                  e.preventDefault();
260	                                  const wasMonitored = isMonitored(scan.url);
261	                                  toggleMonitoring(scan.url);
262	                                  toast.success(
263	                                    wasMonitored
264	                                      ? "Monitoring disabled for this URL"
265	                                      : "Monthly monitoring enabled — you'll get alerts when the score drops"
266	                                  );
267	                                }}
268	                              >
269	                                {isMonitored(scan.url) ? (
270	                                  <><BellOff className="mr-2 h-3.5 w-3.5 text-muted-foreground" />Stop Monitoring</>
271	                                ) : (
272	                                  <><Bell className="mr-2 h-3.5 w-3.5" />Monitor Monthly</>
273	                                )}
274	                              </DropdownMenuItem>
275	                            ) : (
276	                              <DropdownMenuItem disabled className="opacity-50">
277	                                <Bell className="mr-2 h-3.5 w-3.5" />
278	                                Monitor Monthly
279	                                <Badge variant="outline" className="ml-auto text-2xs border-amber-200 bg-amber-50 text-amber-700">Pro</Badge>
280	                              </DropdownMenuItem>
281	                            )}
282	                            <DropdownMenuSeparator />
283	                            <DropdownMenuItem
284	                              className="text-red-600"
285	                              onClick={(e) => {
286	                                e.preventDefault();
287	                                handleDelete(scan.id, hostname);
288	                              }}
289	                            >
290	                              <Trash2 className="mr-2 h-3.5 w-3.5" /> Delete
291	                            </DropdownMenuItem>
292	                          </DropdownMenuContent>
293	                        </DropdownMenu>
294	                      </div>
295	
296	                      {/* Score */}
297	                      <div className="my-4 flex flex-col items-center gap-1">
298	                        {scan.overall_score !== null ? (
299	                          <>
300	                            <ScoreRing score={scan.overall_score} size={80} strokeWidth={5} showLabel={false} />
301	                            <span className={cn("text-sm font-semibold tabular-nums", getScoreColor(scan.overall_score))}>
302	                              {getScoreLabel(scan.overall_score)}
303	                            </span>
304	                          </>
305	                        ) : (
306	                          <div className="flex h-20 w-20 items-center justify-center rounded-full border-4 border-border/40">
307	                            <span className="text-xs text-muted-foreground">N/A</span>
308	                          </div>
309	                        )}
310	                      </div>
311	
312	                      {/* Stats */}
313	                      <div className="flex items-center justify-between text-xs text-muted-foreground">
314	                        <span>
315	                          {scan.issues_found} issues
316	                          {scan.critical_issues > 0 && (
317	                            <span className="ml-1 font-medium text-red-500">&middot; {scan.critical_issues} critical</span>
318	                          )}
319	                        </span>
320	                        <Badge variant="outline" className="text-2xs capitalize">
321	                          {scan.page_type}
322	                        </Badge>
323	                      </div>
324	
325	                      {/* Date + Status */}
326	                      <div className="mt-3 flex items-center justify-between border-t border-border/40 pt-3">
327	                        <span className="text-xs text-muted-foreground">
328	                          {formatDate(scan.created_at)}
329	                        </span>
330	                        {scan.status === "completed" ? (
331	                          <Badge variant="outline" className="border-emerald-200/80 bg-emerald-50/50 text-emerald-700 text-2xs">
332	                            Completed
333	                          </Badge>
334	                        ) : scan.status === "analyzing" ? (
335	                          <Badge variant="outline" className="border-amber-200/80 bg-amber-50/50 text-amber-700 text-2xs animate-pulse">
336	                            Analyzing
337	                          </Badge>
338	                        ) : (
339	                          <Badge variant="outline" className="text-2xs capitalize">{scan.status}</Badge>
340	                        )}
341	                      </div>
342	
343	                      {/* Monitoring indicator */}
344	                      {canMonitor && isMonitored(scan.url) && (
345	                        <div className="flex items-center gap-1.5 mt-2 pt-2 border-t border-border/40">
346	                          <Bell className="h-3 w-3 text-primary" />
347	                          <span className="text-2xs text-primary font-medium">Monitoring active</span>
348	                        </div>
349	                      )}
350	                    </CardContent>
351	                  </Card>
352	                </Link>
353	              );
354	            })}
355	          </div>
356	        ) : (
357	          <EmptyState
358	            icon={ScanLine}
359	            title="No reports found"
360	            description={
361	              search || statusFilter !== "all" || scoreFilter !== "all"
362	                ? "Try adjusting your filters to find what you're looking for."
363	                : "Run your first CRO audit to see results here."
364	            }
365	            actionLabel="Start New Scan"
366	            actionHref="/scan"
367	          />
368	        )}
369	      </div>
370	    </PageTransition>
371	  );
372	};
373	
374	export default Reports;
