34	/** Generate a stable teaser score 45–72 for an unauthenticated guest scan */
35	function generateTeaserScore(url: string): number {
36	  let hash = 0;
37	  for (let i = 0; i < url.length; i++) {
38	    hash = (hash * 31 + url.charCodeAt(i)) & 0xffffffff;
39	  }
40	  return 45 + (Math.abs(hash) % 28);
41	}
42	
43	/** Basic URL validation — checks structure, not reachability */
44	function isValidUrl(str: string): boolean {
45	  try {
46	    const url = new URL(str.startsWith("http") ? str : `https://${str}`);
47	    return url.protocol === "https:" || url.protocol === "http:";
48	  } catch {
49	    return false;
50	  }
51	}
