71	// Resolve the CTA label based on current plan vs tier
72	function getCtaLabel(
73	  tierPlan: PlanType,
74	  currentPlan: PlanType | null,
75	  defaultLabel: string
76	): string {
77	  if (!currentPlan) return defaultLabel;
78	  if (currentPlan === tierPlan) return "Current Plan";
79	  if (tierPlan === "free") return "Downgrade to Free";
80	
81	  const planOrder: PlanType[] = ["free", "pro", "agency"];
82	  const currentIndex = planOrder.indexOf(currentPlan);
83	  const tierIndex = planOrder.indexOf(tierPlan);
84	
85	  if (tierIndex > currentIndex) return `Upgrade to ${tierPlan === "pro" ? "Pro" : "Agency"}`;
86	  return `Switch to ${tierPlan === "pro" ? "Pro" : "Agency"}`;
87	}
