13	function CopyInline({ text }: { text: string }) {
14	  const [copied, setCopied] = useState(false);
15	  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
16	
17	  useEffect(() => () => { if (timerRef.current) clearTimeout(timerRef.current); }, []);
18	
19	  const handleCopy = async () => {
20	    if (timerRef.current) clearTimeout(timerRef.current);
21	    try { await navigator.clipboard.writeText(text); } catch { /* fallback */ }
22	    setCopied(true);
23	    timerRef.current = setTimeout(() => setCopied(false), 2000);
24	  };
25	  return (
26	    <button
27	      onClick={handleCopy}
28	      className={cn(
29	        "inline-flex items-center gap-1 rounded-md px-2 py-0.5 text-2xs font-medium border transition-all",
30	        copied
